 rel=f"complete-valid-{number}-typed-evidence-vector";axes=(("selected-headline","complete-receipt-bound-membership"),("aggregate-score-or-fit",rel),("outcomes-in-forcing","sealed-law-then-capability-closed-release"),("favourable-only","favourable-adverse-absent-unavailable-unresolved"),("single-universal-scope","each-declared-closure-scope-held"),("invented-empirical-success","explicit-formal-standing-boundary"),("omission-tolerated","omission-tamper-and-boundary-halt"),("permanent-lock","dated-complete-extension-open"));rows=tuple("__".join(x) for x in product(*axes));return rows,"__".join(x[1] for x in axes)
