 cid,root=sys.argv[1],Path(sys.argv[2]);sealed=json.loads(Path(sys.argv[3]).read_text());number=cid.rsplit("-",1)[-1];reg=json.loads((root/"census/materials_valid_001_012_dependency_registry_v1.json").read_text());vector=json.loads((root/"experiments/external_sources/materials/valid_001_012_complete_empirical_vector_v1.json").read_text());body=dict(vector);identity=body.pop("complete_vector_identity");members=tuple(reg["vector_claim_ids"][number]);rows_by={x["claim_id"]:x for x in vector["claims"]};census={x["claim_id"]:x for x in json.loads((root/"census/claims.json").read_text())["claims"]};complete=identity==digest(body)==reg["evidence_vector_identity"] and len(members)==reg["vector_claim_counts"][number] and len(set(members))==len(members) and all(x in rows_by and number in rows_by[x]["vector_memberships"] and x in census and current_cert(root,x,census[x]["receipt_hash"]) for x in members);generated,u=surface(number);received=tuple(x["candidate_id"] for x in sealed["census"]["candidates"]);dec={x["candidate_id"]:bool(x["survives"]) for x in sealed["decisions"]};expected={x:x==u for x in generated};controls=sealed["controls"];passed=all((received==generated,len(received)==len(set(received))==256,dec==expected,sum(expected.values())==1,len(controls)==4,all(x["passed"] for x in controls),sealed["closure"]["scope"]=="depth_independent",complete));print(json.dumps({"passed":passed,"validated_seal_hash":sealed["seal_hash"],"recomputed_from_declared_inputs":True,"certificate":{"candidate_count":len(received),"unique_survivor_count":sum(expected.values()),"complete_member_count":len(members),"complete_vector_reconstruction":complete}}));raise SystemExit(0 if passed else 1)
